mapper.select:
SELECT COLUMN_NAME,COMMENTS FROM (SELECT DISTINCT B.COLUMN_NAME COLUMN_NAME, A.COMMENTS COMMENTS ,B.COLUMN_ID COLUMN_ID FROM USER_COL_COMMENTS A ,ALL_TAB_COLUMNS B WHERE A.TABLE_NAME = B.TABLE_NAME AND A.COLUMN_NAME = B.COLUMN_NAME
AND A.TABLE_NAME = #{tableId,jdbcType=CHAR}
) ORDER BY COLUMN_ID
